import fs from 'node:fs/promises';
import path from 'node:path';
import { z } from 'zod';
import { firstCommand, run } from '../utils/shell';
import { capOutput } from '../utils/text';
import { defineTool, toolFail, toolOk, type McpModule, type ToolResult } from './types';

/**
 * MCP Godot — project scaffolding, GDScript authoring and headless runs.
 *
 * Uses whichever Godot 4 binary is on PATH (or $GODOT_BIN). Generated files
 * target the Godot 4.x text formats (project.godot config_version=5,
 * scene format=3) so they open cleanly in the editor.
 */

const GODOT_CANDIDATES = ['godot', 'godot4', 'godot-headless', 'Godot'];

async function godotBinary(): Promise<string | null> {
  const explicit = process.env.GODOT_BIN;
  if (explicit) {
    const result = await run(explicit, ['--version'], { timeoutMs: 8000 });
    if (result.code === 0) return explicit;
  }
  return firstCommand(GODOT_CANDIDATES);
}

function inside(workspace: string, target: string): string {
  const absolute = path.resolve(workspace, target);
  if (!absolute.startsWith(path.resolve(workspace))) throw new Error('Path must be inside the workspace.');
  return absolute;
}

const GD_TEMPLATES = {
  node: (name: string) => `extends Node
## ${name} — generated by AI-FREEBUFF MCP

func _ready() -> void:
\tprint("${name} ready")

func _process(delta: float) -> void:
\tpass
`,
  node2d: (name: string) => `extends Node2D
## ${name} — generated by AI-FREEBUFF MCP

@export var speed: float = 220.0

func _ready() -> void:
\tprint("${name} online")

func _process(delta: float) -> void:
\tposition.x += speed * delta
`,
  character: (name: string) => `extends CharacterBody2D
## ${name} — generated by AI-FREEBUFF MCP

@export var speed: float = 180.0
@export var jump_velocity: float = -420.0

var gravity: float = ProjectSettings.get_setting("physics/2d/default_gravity", 980.0)

func _physics_process(delta: float) -> void:
\tif not is_on_floor():
\t\tvelocity.y += gravity * delta
\tvar direction := Input.get_axis("ui_left", "ui_right")
\tvelocity.x = direction * speed
\tmove_and_slide()
`,
  singleton: (name: string) => `extends Node
## ${name} — autoload singleton generated by AI-FREEBUFF MCP

signal state_changed(next: String)

var state: String = "idle"

func set_state(next: String) -> void:
\tif state == next:
\t\treturn
\tstate = next
\tstate_changed.emit(next)
`,
} as const;

async function writeProjectSkeleton(root: string, projectName: string, template: '2d' | '3d' | 'ui'): Promise<string[]> {
  const created: string[] = [];
  const projectFile = path.join(root, 'project.godot');
  const renderer = template === '3d' ? 'forward_plus' : 'mobile';
  const mainScript = template === 'ui' ? 'node' : 'node2d';

  const projectGodot = `; Engine configuration file — generated by AI-FREEBUFF MCP
; Edit from the Godot editor for best results.

config_version=5

[application]

config/name="${projectName}"
run/main_scene="res://scenes/main.tscn"
config/features=PackedStringArray("4.3", "${template === '3d' ? 'Forward Plus' : 'Mobile'}")
config/icon="res://icon.svg"

[display]

window/size/viewport_width=1280
window/size/viewport_height=720
window/stretch/mode="canvas_items"

[rendering]

renderer/rendering_method="${renderer}"
renderer/rendering_method.mobile="${renderer}"
environment/defaults/default_clear_color=Color(0.02, 0.02, 0.06, 1)
`;

  const mainScriptBody = `extends ${template === 'ui' ? 'Control' : 'Node2D'}
## Main scene controller — generated by AI-FREEBUFF MCP

func _ready() -> void:
\tprint("${projectName} :: boot")

func _process(delta: float) -> void:
\tpass
`;

  const scene = `[gd_scene load_steps=2 format=3]

[ext_resource type="Script" path="res://scripts/main.gd" id="1_main"]

[node name="Main" type="${template === 'ui' ? 'Control' : 'Node2D'}"]
layout_mode = 3
anchors_preset = 15
script = ExtResource("1_main")
`;

  const icon = `<svg xmlns="http://www.w3.org/2000/svg" width="128" height="128" viewBox="0 0 128 128">
  <rect width="128" height="128" rx="24" fill="#05050A"/>
  <text x="64" y="86" font-family="monospace" font-size="64" font-weight="bold"
        text-anchor="middle" fill="#06B6D4">FB</text>
</svg>
`;

  const files: Array<[string, string]> = [
    [projectFile, projectGodot],
    [path.join(root, 'scripts', 'main.gd'), mainScriptBody],
    [path.join(root, 'scenes', 'main.tscn'), scene],
    [path.join(root, 'icon.svg'), icon],
    [path.join(root, '.gitignore'), '.godot/\nexport/\n*.tmp\n'],
    [
      path.join(root, 'README.md'),
      `# ${projectName}\n\nGenerated by AI-FREEBUFF MCP.\n\n- Engine: Godot 4.x\n- Main scene: \`scenes/main.tscn\`\n- Entry script: \`scripts/main.gd\` (${mainScript} template)\n\nOpen with \`godot --path .\` or the editor.\n`,
    ],
  ];

  for (const [file, content] of files) {
    await fs.mkdir(path.dirname(file), { recursive: true });
    await fs.writeFile(file, content, 'utf8');
    created.push(file);
  }
  return created;
}

const info = defineTool({
  name: 'godot_info',
  title: 'Godot info',
  description: 'Detect the Godot binary and report its version.',
  params: '(no arguments)',
  danger: 'safe',
  schema: z.object({}),
  async run() {
    const binary = await godotBinary();
    if (!binary) {
      return toolFail('Godot not found.\nFix: download Godot 4 for arm64, then set GODOT_BIN=/path/to/godot.');
    }
    const version = await run(binary, ['--version'], { timeoutMs: 15_000 });
    return toolOk(`binary : ${binary}\nversion: ${(version.stdout || version.stderr).trim()}`);
  },
});

const projectCreate = defineTool({
  name: 'godot_project_create',
  title: 'Create Godot project',
  description: 'Scaffold a runnable Godot 4 project (project.godot, scene, script, icon).',
  params: 'name:string, dir?:string, template?:"2d"|"3d"|"ui"',
  danger: 'write',
  schema: z.object({
    name: z.string().min(1).regex(/^[A-Za-z0-9 _-]+$/),
    dir: z.string().optional(),
    template: z.enum(['2d', '3d', 'ui']).optional(),
  }),
  async run(args, ctx) {
    const folder = args.dir ?? args.name.replace(/\s+/g, '-').toLowerCase();
    const root = inside(ctx.workspace, folder);
    const existing = await fs.readdir(root).catch(() => [] as string[]);
    if (existing.includes('project.godot')) return toolFail(`${folder} already contains a project.godot.`);
    const created = await writeProjectSkeleton(root, args.name, args.template ?? '2d');
    return toolOk(`✔ Godot project "${args.name}" ready in ${path.relative(ctx.workspace, root)}/\n${created
      .map((file) => `  ${path.relative(root, file)}`)
      .join('\n')}`);
  },
});

const scriptWrite = defineTool({
  name: 'godot_script_write',
  title: 'Write GDScript',
  description: 'Write a GDScript file from a template or explicit content.',
  params: 'project:string, path:string, template?:string, content?:string, className?:string',
  danger: 'write',
  schema: z.object({
    project: z.string().min(1),
    path: z.string().min(1).refine((value) => value.endsWith('.gd'), 'path must end with .gd'),
    template: z.enum(['node', 'node2d', 'character', 'singleton']).optional(),
    content: z.string().optional(),
    className: z.string().optional(),
  }),
  async run(args, ctx) {
    if (!args.content && !args.template) return toolFail('Provide either content or template.');
    const projectRoot = inside(ctx.workspace, args.project);
    const target = inside(projectRoot, args.path);
    const body = args.content ?? GD_TEMPLATES[args.template ?? 'node'](args.className ?? path.basename(args.path, '.gd'));
    await fs.mkdir(path.dirname(target), { recursive: true });
    await fs.writeFile(target, body.endsWith('\n') ? body : `${body}\n`, 'utf8');
    return toolOk(`✔ wrote ${path.relative(ctx.workspace, target)} (${body.split('\n').length} lines)`);
  },
});

const sceneWrite = defineTool({
  name: 'godot_scene_write',
  title: 'Write scene',
  description: 'Write a .tscn scene — pass raw Godot text or let it build a minimal root node.',
  params: 'project:string, path:string, content?:string, rootName?:string, rootType?:string, script?:string',
  danger: 'write',
  schema: z.object({
    project: z.string().min(1),
    path: z.string().min(1).refine((value) => value.endsWith('.tscn'), 'path must end with .tscn'),
    content: z.string().optional(),
    rootName: z.string().optional(),
    rootType: z.string().optional(),
    script: z.string().optional(),
  }),
  async run(args, ctx) {
    const projectRoot = inside(ctx.workspace, args.project);
    const target = inside(projectRoot, args.path);
    let body = args.content;
    if (!body) {
      const header = args.script ? '[gd_scene load_steps=2 format=3]' : '[gd_scene format=3]';
      const ext = args.script
        ? `\n\n[ext_resource type="Script" path="res://${args.script.replace(/^res:\/\//, '')}" id="1_script"]`
        : '';
      const scriptLine = args.script ? '\nscript = ExtResource("1_script")' : '';
      body = `${header}${ext}\n\n[node name="${args.rootName ?? 'Root'}" type="${args.rootType ?? 'Node2D'}"]${scriptLine}\n`;
    }
    await fs.mkdir(path.dirname(target), { recursive: true });
    await fs.writeFile(target, body.endsWith('\n') ? body : `${body}\n`, 'utf8');
    return toolOk(`✔ wrote scene ${path.relative(ctx.workspace, target)}`);
  },
});

const check = defineTool({
  name: 'godot_check',
  title: 'Import / validate project',
  description: 'Run a headless editor import pass and surface script/parse errors.',
  params: 'project:string',
  danger: 'write',
  schema: z.object({ project: z.string().min(1) }),
  async run(args, ctx) {
    const binary = await godotBinary();
    if (!binary) return toolFail('Godot not found. Set GODOT_BIN.');
    const root = inside(ctx.workspace, args.project);
    const result = await run(binary, ['--headless', '--path', root, '--editor', '--quit'], { timeoutMs: 120_000 });
    const output = `${result.stdout}\n${result.stderr}`.trim();
    const problems = output
      .split('\n')
      .filter((line) => /(error|failed|invalid|expected)/i.test(line))
      .slice(0, 50)
      .join('\n');
    return toolOk(
      `${result.code === 0 ? '✔ import pass' : `⚠ exited ${result.code}`}\n` +
        (problems ? `\n${capOutput(problems, 6000)}` : '\nNo parse errors reported.'),
    );
  },
});

const runScene = defineTool({
  name: 'godot_run',
  title: 'Run project',
  description: 'Run a project headlessly for a few frames to verify it boots.',
  params: 'project:string, scene?:string, headless?:boolean, timeoutMs?:number',
  danger: 'write',
  schema: z.object({
    project: z.string().min(1),
    scene: z.string().optional(),
    headless: z.boolean().optional(),
    timeoutMs: z.number().int().min(2000).max(300_000).optional(),
  }),
  async run(args, ctx) {
    const binary = await godotBinary();
    if (!binary) return toolFail('Godot not found. Set GODOT_BIN.');
    const root = inside(ctx.workspace, args.project);
    const flags = ['--path', root];
    if (args.scene) flags.push(inside(root, args.scene));
    if (args.headless !== false) flags.push('--headless');
    flags.push('--quit-after', '120');
    const result = await run(binary, flags, { timeoutMs: args.timeoutMs ?? 60_000 });
    const output = `${result.stdout}\n${result.stderr}`.trim();
    if (result.timedOut) return toolFail('Run timed out — the project may be stuck in _ready() or a loop.');
    return result.code === 0
      ? toolOk(`✔ project ran (${result.durationMs}ms)\n${capOutput(output, 8000)}`)
      : toolFail(`Godot exited ${result.code}\n${capOutput(output, 8000)}`);
  },
});

const listFiles = defineTool({
  name: 'godot_list',
  title: 'List project files',
  description: 'List scenes and scripts inside a Godot project folder.',
  params: 'project:string',
  danger: 'safe',
  schema: z.object({ project: z.string().min(1) }),
  async run(args, ctx) {
    const root = inside(ctx.workspace, args.project);
    const found: string[] = [];
    async function walk(dir: string, depth: number): Promise<void> {
      if (depth < 0) return;
      const entries = await fs.readdir(dir, { withFileTypes: true }).catch(() => []);
      for (const entry of entries) {
        if (entry.name === '.godot' || entry.name.startsWith('.')) continue;
        const full = path.join(dir, entry.name);
        if (entry.isDirectory()) await walk(full, depth - 1);
        else if (/\.(gd|tscn|tres|godot|cfg)$/.test(entry.name)) found.push(path.relative(root, full));
      }
    }
    await walk(root, 5);
    return toolOk(found.length ? found.join('\n') : '(no Godot assets found)');
  },
});

const exportProject = defineTool({
  name: 'godot_export',
  title: 'Export build',
  description: 'Export using an existing preset in export_presets.cfg.',
  params: 'project:string, preset:string, output:string, release?:boolean',
  danger: 'write',
  schema: z.object({
    project: z.string().min(1),
    preset: z.string().min(1),
    output: z.string().min(1),
    release: z.boolean().optional(),
  }),
  async run(args, ctx) {
    const binary = await godotBinary();
    if (!binary) return toolFail('Godot not found. Set GODOT_BIN.');
    const root = inside(ctx.workspace, args.project);
    const presets = await fs.readFile(path.join(root, 'export_presets.cfg'), 'utf8').catch(() => null);
    if (!presets) return toolFail('export_presets.cfg is missing. Create an export preset in the Godot editor first.');
    if (!presets.includes(`name="${args.preset}"`)) return toolFail(`Preset "${args.preset}" not found in export_presets.cfg.`);
    const out = inside(ctx.workspace, args.output);
    await fs.mkdir(path.dirname(out), { recursive: true });
    const mode = args.release === false ? '--export-debug' : '--export-release';
    const result = await run(binary, ['--headless', '--path', root, mode, args.preset, out], { timeoutMs: 600_000 });
    const output = `${result.stdout}\n${result.stderr}`.trim();
    return result.code === 0
      ? toolOk(`✔ exported → ${path.relative(ctx.workspace, out)}\n${capOutput(output, 6000)}`)
      : toolFail(`Export failed (${result.code})\n${capOutput(output, 6000)}`);
  },
});

export const godotMcp: McpModule = {
  id: 'godot',
  name: 'MCP Godot',
  blurb: 'Godot 4 scaffolding, GDScript, headless builds.',
  version: '1.0.0',
  tools: [info, projectCreate, scriptWrite, sceneWrite, check, runScene, listFiles, exportProject],
  async probe() {
    const binary = await godotBinary();
    if (!binary) return { status: 'degraded', detail: 'Godot binary not found — set GODOT_BIN' };
    const version = await run(binary, ['--version'], { timeoutMs: 8000 });
    return { status: 'ready', detail: `${binary} · ${(version.stdout || version.stderr).trim()}` };
  },
};
